def apply_op(op, a, b):
    if op == "+":
        return a + b
    if op == "-":
        return a - b  # This returns a - b
    if op == "*":
        return a * b
    if op == "/":
        return a / b
    raise ValueError(op)

def evaluate(expr):
    stack = []
    for tok in expr.split():
        print(f"Processing token: {tok}, stack before: {stack}")
        if tok in ("+", "-", "*", "/"):
            b = stack.pop()
            a = stack.pop()
            result = apply_op(tok, a, b)  # a - b when op is "-"
            print(f"  Op '{tok}': a={a}, b={b}, result={result}")
            stack.append(result)
        else:
            stack.append(float(tok))
    return stack[0]

